package dex.cosmetics.config

import dex.cosmetics.DexCosmetics
import dex.cosmetics.config.ConfigPaths.configDir
import dex.cosmetics.config.ConfigPaths.cosmeticsDir
import dex.cosmetics.config.ConfigPaths.guiDir
import java.nio.file.Files
import kotlin.io.path.createDirectories
import kotlin.io.path.extension

/** Seeds editable assets without replacing server owners' files. */
object DefaultAssets {
    /** Generated by Gradle from the resource tree, including animation metadata. */
    internal fun bundledResources(): List<String> =
        requireNotNull(javaClass.getResourceAsStream("/default_cosmetics/index.txt")) {
                "Bundled asset index is missing"
            }
            .bufferedReader()
            .use { it.readLines().filter(String::isNotBlank) }

    private fun hasAnyCosmeticFile(): Boolean =
        Files.walk(cosmeticsDir).use { stream ->
            stream.anyMatch { Files.isRegularFile(it) && it.extension in setOf("json", "json5") }
        }

    /**
     * First-run seed: if the cosmetics dir has no JSON files yet, copy every bundled default out of
     * the mod jar. Existing files are never overwritten.
     */
    fun copyCosmeticsIfMissing() {
        if (hasAnyCosmeticFile()) return

        val cls = DefaultAssets::class.java
        for (relativePath in bundledResources()) {
            val resourcePath = "/default_cosmetics/$relativePath"
            val stream =
                requireNotNull(cls.getResourceAsStream(resourcePath)) {
                    "Bundled default missing: $resourcePath"
                }
            val target = configDir.resolve(relativePath)
            if (Files.exists(target)) {
                stream.close()
                continue
            }
            target.parent?.createDirectories()
            stream.use { Files.copy(it, target) }
            DexCosmetics.LOGGER.info("Wrote bundled default: $relativePath")
        }
    }

    /**
     * Bundled default carousel-menu art, mapped from classpath resource → path under `gui/`. Seeded
     * on first run so server owners can edit or swap the card faces and chrome. The motion-template
     * layers are NOT seeded — they stay bundled in the jar.
     */
    private val bundledGuiAssets: List<Pair<String, String>> =
        listOf(
            "/assets/dex_cosmetics/textures/gui/cards/hats.png" to "cards/hats.png",
            "/assets/dex_cosmetics/textures/gui/cards/items.png" to "cards/items.png",
            "/assets/dex_cosmetics/textures/gui/cards/effects.png" to "cards/effects.png",
            "/assets/dex_cosmetics/textures/gui/cards/back.png" to "cards/back.png",
            "/assets/dex_cosmetics/textures/gui/cards/balloons.png" to "cards/balloons.png",
            "/assets/dex_cosmetics/textures/gui/cards/pokemon.png" to "cards/pokemon.png",
            "/assets/dex_cosmetics/textures/gui/cards/background.png" to "background.png",
            "/assets/dex_cosmetics/textures/gui/cards/frame.png" to "frame.png",
        )

    /**
     * First-run seed of the editable GUI art into `config/dex_cosmetics/gui/`. Never overwrites.
     */
    fun copyGuiIfMissing() {
        guiDir.resolve("cards").createDirectories()
        val cls = DefaultAssets::class.java
        for ((resource, relative) in bundledGuiAssets) {
            val target = guiDir.resolve(relative)
            if (Files.exists(target)) continue
            val stream =
                cls.getResourceAsStream(resource)
                    ?: run {
                        DexCosmetics.LOGGER.warn("Bundled GUI asset missing: $resource")
                        return@run null
                    }
                    ?: continue
            target.parent?.createDirectories()
            stream.use { Files.copy(it, target) }
            DexCosmetics.LOGGER.info("Wrote default GUI asset: $relative")
        }
    }
}
